\textit{How fast does the
tail probability 
\begin{equation}
\mathbb{P}(|X_{1}-x_{0}|>R)\label{eq:TailProb}
\end{equation}
decay as $R$ goes to infinity?}

If $\alpha\in(0,1)$ and $f$ is absolutely continuous, the left fractional
derivative can also be computed as
\begin{equation}\label{eq:FracDer}
(D_{0^{+}}^{\alpha}f)(t):=\frac{1}{\Gamma(1-\alpha)}\Big[\frac{f(0)}{t^{\alpha}}+\int_{0}^{t}(t-s)^{-\alpha}\dot{f}(s)ds\Big].
\end{equation}

\label{thm:CMFracRep}Let $H\in(0,1).$ There is a linear isomorphism
\begin{equation}
{\cal K}_{H}:L^{2}([0,1])\rightarrow I_{0^{+}}^{H+1/2}\big(L^{2}([0,1])\big)\label{eq:KHIso}
\end{equation}
which is defined by 
\[
{\cal K}_{H}\varphi:=\begin{cases}
c_{H}\cdot I_{0^{+}}^{1}\big(t^{H-1/2}I_{0^{+}}^{H-1/2}\big(s^{1/2-H}\varphi(s)\big)(t)\big), & H\in(1/2,1);\\
c_{H}\cdot I_{0^{+}}^{2H}\big(t^{1/2-H}I_{0^{+}}^{1/2-H}\big(s^{H-1/2}\varphi(s)\big)(t)\big), & H\in(0,1/2].
\end{cases}
\]
Here $c_{H}$ is a universal constant depending only on $H$. In addition,
one has $\bar{{\cal H}}=I_{0^{+}}^{H+1/2}(L^{2}([0,1];\mathbb{R}^{d}))$
and 
\[
\|h\|_{\bar{{\cal H}}}=\big\|{\cal K}_{H}^{-1}h\big\|_{L^{2}([0,1];\mathbb{R}^{d})}
\]
for all $h\in\bar{{\cal H}}$.

\label{lem:EquivNorm}

Let $H\in (1/2,1).$ Then one has 
\begin{equation}
\|h\|_{\bar{{\cal H}}}^{2}\asymp_{H}\|D_{0^+}^{H-1/2}\dot{h}\|^2_{L^2([0,1])}\asymp_{H}\|\dot{h}\|_{L^{2}([0,1])}^{2}+\int_{0}^{1}\int_{0}^{1}\frac{\big|\dot{h}_{t}-\dot{h}_{s}\big|^{2}}{|t-s|^{2H}}dsdt\label{eq:EquivFracNorm}
\end{equation}
for all $h\in \bar{\mathcal{H}}$. Here $a \asymp_{H} b$ means $c_H b \leqslant a \leqslant C_H b$ for some positive constants $c_H,C_H$ depending only on $H$.

Let $H\in (0,1/2)$. Then one has \begin{equation}
\big(K_{H}^{-1}h\big)(t)=\int_{0}^{t}Q(t,s)\dot{h}_{s}ds\label{eq:InvKForm}
\end{equation}
for any absolutely continuous $h$, where 
\[
Q(t,s):=c_{H}t^{H-1/2}s^{1/2-H}(t-s)^{-(1/2+H)}
\]
and $c_{H}$ is an explicit constant depending only on $H$.

\label{thm:RoughLowG}Let $X_{t}$ be the solution to the SDE (\ref{eq:SDEIntro}) with  $H\in(1/4,1/2)$
and $V_{i}\in C_{b}^{\infty}$. Suppose that Condition (G) holds.
Then there exist positive constants $C_{1},C_{2}$ depending only
on $H,V,F,K,a$, such that 
\begin{equation}
\mathbb{P}(|X_{1}-x_{0}|>R)\geqslant C_{1}e^{-C_{2}R^{2H+1}}\label{eq:RoughLowG}
\end{equation}
for all large $R$.

First of all, recall from \cite[Theorem 9.33]{FV10} that 
\begin{equation}
d_{p\text{-var}}\big(T_{q^{I}}{\bf b},T_{q^{I}}{\bf 1}\big)\leqslant C_{p,K}\|{\bf b}\|_{p\text{-var}}\label{eq:TranCty}
\end{equation}
uniformly for all ${\bf b}$ and $q^{I}$ satisfying $\|{\bf b}\|_{p\text{-var}}\leqslant1$
and $\|q^{I}\|_{1\text{-var}}\leqslant K$. Let $(Y_{t}^{0})_{t\in I}$
be the solution to the RDE 
\begin{equation}
d\bar{Y}_{t}^{x}=\sum_{i=1}^{d}V_{i}(\bar{Y}_{t}^{x})d(T_{q^{I}}{\bf b})^{i},\quad\bar{Y}_{s}^{x}=x.\label{eq:BarYxEqn}
\end{equation}
Respectively, let $z_{t}$ be the solution to the ODE
\[
dz_{t}^{x}=\sum_{i=1}^{d}V_{i}(z_{t}^{x})d(q_{t}^{I})^{i},\quad z_{s}^{x}=x.
\]
Note that $z_{s+\delta}^{x}=\Psi_{q^{I}}(x).$ According to the standard
RDE continuity estimate (see \cite[Theorem 10.38]{FV10}) and (\ref{eq:TranCty}),
one has 
\begin{equation}
\big|\bar{Y}_{s+\delta}^{x}-\Psi_{q^{I}}(x)\big|\leqslant C_{p,V,K}\|{\bf b}\|_{p\text{-var}}.\label{eq:BarYPsi}
\end{equation}
On the other hand, the equation (\ref{eq:YxIEqn}) of $Y_{t}^{x}$
can be written as
\begin{equation}
dY_{t}^{x}=\sum_{i=1}^{d}V_{i}(Y_{t}^{x})d(T_{q^{I}}{\bf b})^{i}+\delta V_{0}(Y_{t}^{x})d\tau_{t}^{I},\label{eq:YxEqnDel}
\end{equation}
where $\tau_{t}^{I}\triangleq\frac{t-s}{\delta}$ satisfies $\|\tau^{I}\|_{1\text{-var}}=1$.
By applying the RDE continuity estimate with drift (see \cite[Theorem 12.10]{FV10})
to the equations (\ref{eq:BarYxEqn}, \ref{eq:YxEqnDel}), one finds
that 
\begin{equation}
\big|Y_{s+\delta}^{x}-\bar{Y}_{s+\delta}^{x}\big|\leqslant C_{p,V,K}\delta.\label{eq:YBarY}
\end{equation}
The desired estimate follows by combining (\ref{eq:BarYPsi}) and
\ref{eq:YBarY}.

\label{lem:CMEst}Let $K>0$ be a given number. There exists a positive
constant $C_{H,K}$, such that the following estimate 
\begin{equation}\label{eq:CmEstRoughLow}
\|h^{(n)}\|_{\bar{{\cal H}}}\leqslant C_{H}Kn^{H+1/2}
\end{equation}
holds uniformly for all $n\geqslant1$ and all absolutely continuous
paths $h^{(n)}$ satisfying $\|\dot{h}^{(n)}\|_{L^{\infty}}\leqslant Kn$
and $h_{t_{k-1}}^{^{(n)}}=h_{t_{k}}^{(n)}$ for every $k=1,\cdots,n.$

\label{thm:GenLowRough}
Consider the SDE (\ref{eq:SDEIntro}) with $H\in (1/4,1/2)$. Suppose that the vector fields are $C_b^\infty$ and uniformly elliptic in the sense of (\ref{eq:UE}). Then there exist positive constants depending only on $H$ and the vector fields, such that the estimate
\begin{equation}\label{eq:GenLowRough}
\mathbb{P}\big(|X_{1}-x_{0}|>R\big)\geqslant C_{1}e^{-C_{2}R^{2}}
\end{equation}
holds for all large $R$.

\label{lem:RedOsEv}The inclusion 
\begin{align}
\big\{|X_{1}|>n\big\}\subseteq & \Big\{\text{there exist }0<s_{1}<t_{1}<\cdots<s_{n}<t_{n}<1,\nonumber \\
 & \ \ \ \text{such that }(-1)^{k-1}(B_{t_{k}}^{1}-B_{s_{k}}^{1})=\frac{1}{2}\ \text{for every }k\Big\}\label{eq:OscilEv}
\end{align}
holds for all $n\geqslant1.$

\label{lem:CMLowVar}The lower estimate 
\begin{equation}
\|h\|_{\bar{{\cal H}}}^{2}\geqslant\frac{a^{2}\big(\sum_{k=1}^{n}l_{k}^{-1}\big)^{2}}{{\rm Var}\big[\sum_{k=1}^{n}\frac{\varepsilon_{k}}{l_{k}}(B_{t_{k}}-B_{s_{k}})\big]}\label{eq:CMLowVar}
\end{equation}
holds uniformly for all $h\in\bar{{\cal H}}$ satisfying
\[
\varepsilon_{k}(h_{t_{k}}-h_{s_{k}})\geqslant a
\]
for every $k=1,\cdots,n,$ where $\varepsilon_{k}:=(-1)^{k-1}$ and
$l_{k}:=t_{k}-s_{k}$.

According to (\ref{eq:VarRep}) and Lemma \ref{lem:fFId}, 
\begin{equation}
{\rm Var}\Big[\sum_{k=1}^{n}\frac{\varepsilon_{k}}{l_{k}}(B_{t_{k}}-B_{s_{k}})\Big]=c_{H}\int_{0}^{\infty}\frac{\|\Delta_{r}F\|_{L^{2}(\mathbb{R})}^{2}}{r^{4-2H}}dr,\label{eq:VarRepF}
\end{equation}
where 
\[
c_{H}:=H(2H-1)(2-2H)(3-2H)
\]
and the function $F(x):=\int_{-\infty}^{x}f(u)du$ with $f$ being
defined by (\ref{eq:f}).

To estimate the RHS of (\ref{eq:VarRepF}), one further writes 
\[
F=\sum_{k=1}^{n/2}F_{k};\quad F_{k}:=\int_{-\infty}^{x}\Big(\frac{{\bf 1}_{I_{2k-1}}(u)}{l_{2k-1}}-\frac{{\bf 1}_{I_{2k}}(u)}{l_{2k}}\Big)du.
\]
It is easy to see that 
\begin{equation}
0\leqslant F_{k}\leqslant1,\quad\int_{\mathbb{R}}|F_{k}'(x)|dx\leqslant2.\label{eq:FkProp}
\end{equation}
In addition, the supports of the $F_{k}$'s are disjoint. We claim
that 
\begin{equation}
\|\Delta_{r}F_{k}\|_{L^{2}(\mathbb{R})}^{2}\leqslant\min\{L_{k}r^{2},2r\}\label{eq:DelFkEst}
\end{equation}
for all $r>0,$ where $L_{k}:=l_{2k-1}^{-1}+l_{2k}^{-1}$. Indeed,
one has 
\[
\big|(\Delta_{r}F_{k})(x)\big|^{2}=\Big|\int_{0}^{r}F_{k}'(x+u)du\Big|^{2}\leqslant r\int_{0}^{r}\big|F_{k}'(x+u)\big|^{2}du.
\]
It follows that 
\begin{equation}
\|\Delta_{r}F_{k}\|_{L^{2}(\mathbb{R})}^{2}\leqslant r^{2}\|F_{k}'\|_{L^{2}(\mathbb{R})}^{2}=L_{k}r^{2}.\label{eq:DelFk1}
\end{equation}
On the other hand, according to (\ref{eq:FkProp}), one also has 
\begin{align}
\|\Delta_{r}F_{k}\|_{L^{2}(\mathbb{R})}^{2} & \leqslant\int_{\mathbb{R}}\big|(\Delta_{r}F_{k})(x)\big|dx\nonumber \\
 & \leqslant\int_{\mathbb{R}}\int_{0}^{r}\big|F_{k}'(x+u)\big|dudx\leqslant2r.\label{eq:DelFk2}
\end{align}
The estimate (\ref{eq:DelFkEst}) thus follows from (\ref{eq:DelFk1})
and (\ref{eq:DelFk2}).

Now consider the decomposition 
\[
(\Delta_{r}F)(x)=\sum_{k=1}^{n/2}(\Delta_{r}F_{k})(x).
\]
Since the $F_{k}$'s have disjoint supports, for every $x\in\mathbb{R}$
there are at most two nonzero terms in the above summation. As a result,
one has 
\[
\big|(\Delta_{r}F)(x)\big|^{2}\leqslant2\sum_{k=1}^{n/2}\big|(\Delta_{r}F_{k})(x)\big|^{2}.
\]
It follows from (\ref{eq:DelFkEst}) that 
\begin{align*}
\int_{0}^{\infty}\frac{\|\Delta_{r}F\|_{L^{2}(\mathbb{R})}^{2}}{r^{4-2H}}dr\leqslant & 2\sum_{k=1}^{n/2}\int_{0}^{\infty}\frac{\|\Delta_{r}F_{k}\|_{L^{2}(\mathbb{R})}^{2}}{r^{4-2H}}dr\\
\leqslant & 2\sum_{k=1}^{n/2}\int_{0}^{\infty}\frac{\min\{L_{k}r^{2},2r\}}{r^{4-2H}}dr\\
= & \frac{2^{2H-1}}{(2H-1)(1-H)}\sum_{k=1}^{n/2}L_{k}^{2-2H}\\
\leqslant & \frac{2^{2H-1}}{(2H-1)(1-H)}\sum_{k=1}^{n/2}\big(l_{2k-1}^{2H-2}+l_{2k}^{2H-2}\big).
\end{align*}
In view of the relation (\ref{eq:VarRepF}), the result thus follows.

\label{lem:FixGdEst}There exist positive constants $C_{1},C_{2}$
depending only on $H$, such that the estimate 
\begin{equation}
\mathbb{P}\big(\varepsilon_{k}(B_{t_{k}}-B_{s_{k}})\geqslant a\ \text{for every }k=1,\cdots n\big)\leqslant C_{1}e^{-C_{2}a^{2}n^{2H+1}}\label{eq:FixGdEst}
\end{equation}
holds uniformly for all $a>0$, $n\geqslant1$ and $0<s_{1}<t_{1}<\cdots<s_{n}<t_{n}<1.$

\label{thm:2DCounter} Let $\eta:[0,\infty)\rightarrow[0,\infty)$ be a smooth function that is constant near the origin and such that  $\eta(r)=r$ for $r\geqslant2.$ Let $B_{t}=(B_{t}^{1},B_{t}^{2})$ be a fractional
Brownian motion with Hurst parameter $H>1/2$. Consider the SDE 
\begin{equation}
dX_{t}=V_{1}(X_{t})dB_{t}^{1}+V_{2}(X_{t})dB_{t}^{2},\quad X_{0}=0\in\mathbb{R}^{2},\label{eq:2DCounter}
\end{equation}
where 
\begin{equation}
\big(V_{1}(x),V_{2}(x)\big)=\left(\begin{array}{cc}
\cos\eta(|x|) & -\sin\eta(|x|)\\
\sin\eta(|x|) & \cos\eta(|x|).
\end{array}\right)\label{eq:2DVFld}
\end{equation}
Then there exist positive constants $C_{1},C_{2}$, such that 
\[
\mathbb{P}\Big(\sup_{0\leqslant t\leqslant1}|X_{t}|>R\Big)\leqslant C_{1}e^{-C_{2}R^{2H+1}}
\]
for all large $R$.

\label{prop:KeyCoer}Let $p\in(H^{-1},2).$ For any $M>0,$ there
exist positive constants $c_{*}$ and $R_{*}$ depending only on $p,H,V$
and $M$, such that the following implication 
\begin{equation}
\sup_{0\leqslant t\leqslant1}|X_{t}^{w+h}|\geqslant R,\ R>R_{*}\implies\|h\|_{\bar{{\cal H}}}\geqslant c_{*}R^{H+1/2}\label{eq:KeyCoer}
\end{equation}
holds uniformly over all $h\in\bar{{\cal H}}$ and all $w\in C^{p\text{-var}}([0,1];\mathbb{R}^{2})$
satisfying $\|w\|_{p\text{-var}}\leqslant M$.

In particular, 
\begin{equation}
\|h\|_{\bar{{\cal H}}}^{2}\geqslant C_{H}\int_{0}^{1}\int_{0}^{1}\frac{\big|\dot{h}_{t}-\dot{h}_{s}\big|^{2}}{|t-s|^{2H}}dsdt.\label{eq:CMLowFrac}
\end{equation}
Next, let $I\subseteq[0,1]$ be an interval which contains an $(a_{0},\theta_{0})$-effective
turn $(A,B)$ of $h$. By definition, it is not hard to see that 
\[
\big|\dot{h}_{s}-\dot{h}_{t}\big|^{2}\geqslant4\sin^{2}\Big(\frac{\theta_{0}}{2}\Big)\cdot|\dot{h}_{s}|\cdot|\dot{h}_{t}|
\]
for $(\mu_{h}\otimes\mu_{h})$-a.e. $(s,t)\in A,B$. As a consequence,
\begin{align}
\int_{I\times I}\frac{\big|\dot{h}_{t}-\dot{h}_{s}\big|^{2}}{|t-s|^{2H}}dsdt & \geqslant4\sin^{2}\Big(\frac{\theta_{0}}{2}\Big)\int_{A\times B}\frac{|\dot{h}_{s}|\cdot|\dot{h}_{t}|}{|t-s|^{2H}}dsdt\nonumber \\
 & \geqslant4\sin^{2}\Big(\frac{\theta_{0}}{2}\Big)\cdot|I|^{-2H}\cdot a_{0}^{2}.\label{eq:CMLowEachI}
\end{align}
Now suppose that $I_{1},\cdots,I_{N}$ are $N$ given disjoint intervals,
each containing an $(a_{0},\theta_{0})$-effective turn. It follows
from (\ref{eq:CMLowEachI}) that
\begin{align}
\int_{0}^{1}\int_{0}^{1}\frac{\big|\dot{h}_{t}-\dot{h}_{s}\big|^{2}}{|t-s|^{2H}}dsdt & \geqslant\sum_{k=1}^{N}\int_{I_{k}\times I_{k}}\frac{\big|\dot{h}_{t}-\dot{h}_{s}\big|^{2}}{|t-s|^{2H}}dsdt\nonumber \\
 & \geqslant4a_{0}^{2}\sin^{2}\Big(\frac{\theta_{0}}{2}\Big)\cdot\sum_{k=1}^{N}|I_{k}|^{-2H}.\label{eq:FracLow}
\end{align}
On the other hand, by using the convexity of $x\mapsto x^{-2H}$ and
the fact that $\sum_{k}|I_{k}|\leqslant1,$ one has
\begin{equation}
\frac{1}{N}\sum_{k=1}^{N}|I_{k}|^{-2H}\geqslant\Big(\frac{1}{N}\sum_{k=1}^{N}|I_{k}|\Big)^{-2H}\geqslant N^{2H}.\label{eq:Conv}
\end{equation}
After combining (\ref{eq:CMLowFrac}), (\ref{eq:FracLow}) and (\ref{eq:Conv}),
one arrives at 
\[
\|h\|_{\bar{{\cal H}}}^{2}\geqslant4C_{H}a_{0}^{2}\sin^{2}\Big(\frac{\theta_{0}}{2}\Big)\cdot N^{2H+1}.
\]
The result follows from the definition of ${\cal N}_{{\rm eff}}(h)$.

\label{lem:NonPertCoer}There exist universal positive constants $C_{1},C_{2}$,
such that the estimate
\begin{equation}
{\cal N}_{{\rm eff}}(h)\geqslant C_{1}R-\frac{C_{2}\|h\|_{1\text{-var}}}{R}\label{eq:NonPertCoer}
\end{equation}
holds uniformly for all $R>4$ and all $h\in\bar{{\cal H}}$ satisfying
$\sup_{0\leqslant t\leqslant1}|X_{t}^{h}|\geqslant R$.

\label{lem:HeavyConcen}Suppose that $I$ does not contain an $(a_{0},\theta_{0})$-effective
turn of $h$ and there is at least one heavy arc with respect to $h|_{I}$.
Then there exists a measurable set $E\subseteq I$ and a unit vector
$v_{*}$, such that 
\begin{equation}
\mu_{h}(E)\leqslant m_{0}a_{0}\label{eq:LightLength}
\end{equation}
and 
\begin{equation}
\angle\Big(\frac{\dot{h}_{t}}{|\dot{h}_{t}|},v_{*}\Big)\leqslant\theta_{0}+\frac{4\pi}{m_{0}}\label{eq:HeavyConcen}
\end{equation}
for $\mu_{h}$-a.e. $t\in I\backslash E$ with $\dot{h}_{t}\neq0$.

We first claim that there is at least one heavy arc with respect to
$h|_{I}.$ Indeed, since $V$ is everywhere orthonormal, one has 
\[
|\dot{X}_{t}^{h}|=|\dot{h}_{t}|\quad\text{for every }t\implies\mu_{h}(I)=\|h\|_{1\text{-var};I}=\|X^{h}\|_{1\text{-var};I}\geqslant3\pi
\]
by assumption. On the other hand, if all arcs were light, according
to (\ref{eq:ParChoice}) one would obtain that 
\[
\mu_{h}(I)\leqslant m_{0}a_{0}=\frac{\pi}{8},
\]
which is a contradiction. Therefore, there is at least one heavy arc.
It follows from Lemma \ref{lem:HeavyConcen} that there exists a measurable
subset $E\subseteq I$ and a unit vector $v_{*}$, such that (\ref{eq:LightLength})
and (\ref{eq:HeavyConcen}) hold.

To prove the lemma, let us write 
\begin{equation}
X_{t}^{h}=r_{t}e^{i\phi_{t}},\dot{h}_{t}=|\dot{h}_{t}|e^{i\alpha_{t}},\quad t\in I.\label{eq:XDotHEqn}
\end{equation}
Here $\phi_{t}$ is any continuous determination of the angular component
of $X_{t}^{h}$; one can fix any $\phi_{u}\in\arg X_{t}^{h}$ and
then determine a unique lifted path $(\phi_{t})_{t\in I}.$ The path
$\alpha_{t}$ is any measurable choice of ${\rm arg}(\dot{h}_{t}/|\dot{h}_{t}|)$,
which is $\mu_{h}$-a.e. defined on $\{t:\dot{h}_{t}\neq0\}$. Since
\[
V(x)=\left(\begin{array}{cc}
\cos|x| & -\sin|x|\\
\sin|x| & \cos|x|
\end{array}\right)
\]
when $|x|\geqslant2$, elementary computation shows that 
\begin{equation}
\dot{r}_{t}=|\dot{h}_{t}|\cos(r_{t}+\alpha_{t}-\phi_{t}),\quad\dot{\phi}_{t}=\frac{1}{r_{t}}|\dot{h}_{t}|\sin(r_{t}+\alpha_{t}-\phi_{t}).\label{eq:RPhiEqn}
\end{equation}
In particular, one has 
\begin{equation}
|\dot{r}_{t}|\leqslant|\dot{h}_{t}|,\quad|\dot{\phi}_{t}|\leqslant\frac{1}{a}|\dot{h}_{t}|\label{eq:DynEstNonPert}
\end{equation}
for all $t\in I$. 

Now suppose on the contrary that $\mu_{h}(I)<\gamma_{0}a.$ The second
relation in (\ref{eq:DynEstNonPert}) implies that 
\[
\sup_{s,t\in I}|\phi_{t}-\phi_{s}|\leqslant\frac{1}{a}\mu_{h}(I)\leqslant\gamma_{0}.
\]
In addition, writing $v_{*}=e^{i\alpha_{*}}$ one knows from (\ref{eq:HeavyConcen})
that 
\[
\angle\big(e^{i\alpha_{t}},e^{i\alpha_{*}}\big)\leqslant\theta_{0}+\frac{4\pi}{m_{0}}
\]
for $\mu_{h}$-a.e. $t\in I\backslash E$. As a result, one has 
\begin{equation}
{\rm dist}_{2\pi}(\alpha_{t}-\phi_{t},\alpha_{*}-\phi_{u})\leqslant\theta_{0}+\frac{4\pi}{m_{0}}+\gamma_{0}\label{eq:AlpPhiDist}
\end{equation}
for $\mu_{h}$-a.e. $t\in I\backslash E$. Here ${\rm dist}_{2\pi}$
denotes the distance modulo $2\pi$ (equivalently, the $S^{1}$-distance).
Let 
\[
\beta_{*}\in[a+m_{0}a_{0},a+3\pi-m_{0}a_{0}]
\]
be a point satisfying 
\begin{equation}
\beta_{*}=\pi-(\alpha_{*}-\phi_{u})\quad\mod2\pi.\label{eq:Beta*}
\end{equation}
Such a $\beta_{*}$ clearly exists since $3\pi-2m_{0}a_{0}>2\pi$
(see (\ref{eq:ParChoice})). It follows that 
\begin{align*}
{\rm dist}_{2\pi}(r_{t}+\alpha_{t}-\phi_{t},\pi) & ={\rm dist}_{2\pi}(r_{t}+\alpha_{t}-\phi_{t},\beta_{*}+(\alpha_{*}-\phi_{u}))\\
 & \leqslant m_{0}a_{0}+\theta_{0}+\frac{4\pi}{m_{0}}+\gamma_{0}\\
 & =\frac{\pi}{8}+\frac{\pi}{8}+\frac{\pi}{8}+\frac{\pi}{8}=\frac{\pi}{2}
\end{align*}
whenever $t\in I\backslash E$ and $r_{t}\in[\beta_{*}-m_{0}a_{0},\beta_{*}+m_{0}a_{0}]$
for $\mu_{h}$-a.e. In particular, 
\begin{equation}
\dot{r}_{t}=|\dot{h}_t|\cos(r_{t}+\alpha_{t}-\phi_{t})\leqslant0\label{eq:NegDotR}
\end{equation}
for all such $t.$ 

To reach a contradiction, let 
\begin{align}
t_{+} & :=\inf\{t\in I:r_{t}=\beta_{*}+m_{0}a_{0}\},\nonumber \\
t_{-} & :=\sup\{t\in I:t<t_{+},r_{t}=\beta_{*}-m_{0}a_{0}\}.\label{eq:tpm}
\end{align}
Both $t_{\pm}$ are well-defined since 
\[
[\beta_{*}-m_{0}a_{0},\beta_{*}+m_{0}a_{0}]\subseteq[a,a+3\pi]
\]
by the construction of $\beta_{*}$. According to the first relation
of (\ref{eq:DynEstNonPert}) along with the estimates (\ref{eq:NegDotR})
and (\ref{eq:LightLength}), one obtains that 
\begin{align*}
2m_{0}a_{0} & =r_{t_{+}}-r_{t_{-}}=\int_{t_{-}}^{t_{+}}\dot{r}_{s}ds\\
 & =\int_{E\cap[t_{-},t_{+}]}\dot{r}_{s}ds+\int_{(I\backslash E)\cap[t_{-},t_{+}]}\dot{r}_{s}ds\\
 & \leqslant\int_{E\cap[t_{-},t_{+}]}\dot{r}_{s}ds\leqslant\mu_{h}(E)\leqslant m_{0}a_{0}.
\end{align*}
This is absurd. Therefore, $\mu_{h}(I)\geqslant\gamma_{0}a.$

\label{lem:WHCty}There exist positive constants $C,\delta$ depending
only on $p$ and $V$, such that the estimate
\begin{equation}
\|X^{w+h}\|_{p\text{-var};I}\leqslant C(\omega_{I}+l_{I})\label{eq:WHCty}
\end{equation}
holds uniformly over all subintervals $I\subseteq[0,1]$, all $h\in C^{1\text{-var}}([0,1];\mathbb{R}^{2})$
and all $w\in C^{p\text{-var }}([0,1];\mathbb{R}^{2})$ satisfying
$\omega_{I}\leqslant\delta$.

According to \cite[Theorem 6.8]{FV10}, one has 
\begin{equation}
\Big|\int_{J}F(X_{t})dw_{t}\Big|\leqslant C_{p,q}\big(\|F\|_{\infty}+\|F(X)\|_{q\text{-var};I}\big)\omega_{I}\label{eq:PertEsPf2}
\end{equation}
for all $J\subseteq I$, where $q\in(p,p')$ is given fixed (see (\ref{eq:PThe})).
On the other hand, by using the simple estimate 
\begin{align*}
|F(X_{t})-F(X_{s})|^{q} & =|F(X_{t})-F(X_{s})|^{q-p}|F(X_{t})-F(X_{s})|^{p}\\
 & \leqslant(2\|F\|_{\infty})^{q-p}(L_{F}|X_{t}-X_{s}|)^{p}
\end{align*}
where $L_{F}$ denotes the Lipschitz constant for $F$, one finds
that 
\[
\|F(X)\|_{q\text{-var};I}\leqslant(2\|F\|_{\infty})^{1-\theta}L_{F}^{\theta}\|X\|_{p\text{-var};I}^{\theta}.
\]
It follows from Lemma \ref{lem:WHCty} that 
\begin{equation}
\|F(X)\|_{q\text{-var};I}\leqslant C_{p,V}(2\|F\|_{\infty})^{1-\theta}L_{F}^{\theta}(\omega_{I}+l_{I})^{\theta},\label{eq:PertEsPf1}
\end{equation}
provided that $\omega_{I}\leqslant\delta$. By substituting (\ref{eq:PertEsPf1})
into (\ref{eq:PertEsPf2}), one obtains the desired estimate (\ref{eq:YoungPert}).

\label{lem:ILengthPert}There exist positive constants $A_{0},\eta_{0}$
depending only on $p,\theta,V$, such that the following statement
holds. Given any control pair $(w,h)$, any $I=[u,v]\subseteq[0,1],$
any $a>2$, whenever $(w,h,X^{w+h})$ satisfies 
\begin{equation}
r_{u}=a,r_{v}=a+3\pi,\quad r_{t}\in[a,a+3\pi]\ \text{for all }t\in I,\label{eq:WHAs1}
\end{equation}
\begin{equation}
a\geqslant A_{0},\omega_{I}\leqslant\delta,\Xi_{I}\leqslant\eta_{0}\label{eq:WHAs2}
\end{equation}
and 
\begin{equation}
\mu_{h}(I)<\frac{\gamma_{0}a}{2},\label{eq:WHAs3}
\end{equation}
the interval $I$ must contain an $(a_{0},\theta_{0})$-effective
turn of $h$.

\label{thm:GenLowYoung}
Consider the SDE (\ref{eq:SDEIntro}) with $H\in(1/2,1).$ Suppose that
the vector fields are $C_{b}^{\infty}$ and uniformly elliptic. Then
there exist positive constants $C_{1},C_{2}$ depending only on $H$
and the vector fields, such that the estimate 
\begin{equation}
\mathbb{P}\big(|X_{1}-x_{0}|>R\big)\geqslant C_{1}e^{-C_{2}R^{2H+1}}\label{eq:WeibullGenYoung}
\end{equation}
holds for all large $R$.

\label{thm:2DPeriodic}Let $V_{1},V_{2}$ be given smooth vector fields
on the torus $\mathbb{T}^{2}=\mathbb{R}^{2}/\mathbb{Z}^{2}.$ Suppose
that they are uniformly elliptic, namely, 
\[
\dim{\rm Span}\{V_{1}(x),V_{2}(x)\}=2
\]
for every $x\in\mathbb{T}^{2}$. Consider the SDE 
\begin{equation}
dX_{t}=\tilde{V}_{1}(X_{t})dB_{t}^{1}+\tilde{V}_{2}(X_{t})dB_{t}^{2},\quad X_{0}=x_{0}\in\mathbb{R}^{2}\label{eq:SDETorus}
\end{equation}
on the universal cover $\mathbb{R}^{2}.$ Here $\tilde{V}_{i}$ is
the canonical periodic lifting of $V_{i}$ on $\mathbb{R}^{2}$ and
$B_{t}=(B_{t}^{1},B_{t}^{2})$ is an fBM with Hurst parameter $H\in(1/2,1)$.
Then there exist positive constants $C_{1},C_{2}$, such that 
\begin{equation}
\mathbb{P}\big(|X_{1}-x_{0}|>R\big)\geqslant C_{1}e^{-C_{2}R^2}\label{eq:GaussLowTorus}
\end{equation}
for all large $R.$

\label{lem:OrbitStab}Let $\lambda^{*}\in(\lambda_{\gamma},1)$ be
a given fixed number. Then there exists $\delta<\varepsilon$, such
that 
\begin{equation}
\phi_{s}(U_{\delta})\subseteq U_{\varepsilon/4}\label{eq:Tub1}
\end{equation}
for all $s\in[0,T]$ and 
\begin{equation}
|z(\phi_{T}(x))|\leqslant\lambda^{*}|z(x)|\label{eq:Tub2}
\end{equation}
for all $x\in U_{\delta}$. Here $\phi_{s}$ denotes the flow of $W$.

\label{lem:IntNumForm}Let $P,Q$ be smooth, simple and closed curves
which intersect transversally and whose homology classes are given
by 
\begin{equation}
[P]=p_{1}\sigma_{1}+p_{2}\sigma_{2},\quad[Q]=q_{1}\sigma_{1}+q_{2}\sigma_{2},\label{eq:IntNumAssump}
\end{equation}
with $p_{i},q_{j}\in\mathbb{Z}$. Then $I(P,Q)=p_{1}q_{2}-p_{2}q_{1}$.

If ${\cal O}_{x}$ is periodic, one trivially has $\omega(x)={\cal O}_{x}=C$.
We therefore assume that ${\cal O}_{x}$ is nonperiodic. By assumption,
let $p\in C\cap\omega(x)$. Then $\phi_{t_{n}}(x)\rightarrow p$ for
some $t_{n}\rightarrow\infty.$ We first claim that $C\subseteq\omega(x)$.
Let $q\in C$. One can write $q=\phi_{t}(p)$ for some $t\geqslant0.$
It follows that $\phi_{t_{n}+t}(x)\rightarrow q$, which implies that
$q\in\omega(x)$. Therefore, $C\subseteq\omega(x)$. 

Conversely, let $q\notin C.$ Our aim is to show that $q\notin\omega(x)$.
Since $C$ is compact, it suffices to show that 
\begin{equation}
\lim_{t\rightarrow\infty}d(\phi_{t}(x),C)=0.\label{eq:OrbAsymC}
\end{equation}
To this end, let $V$ be a flow box centered at $p$ with transversal
$\Sigma$. Since $\phi_{t_{n}}(x)\rightarrow p$ and ${\cal O}_{x}$
is nonperiodic, similar to the proof of Lemma \ref{lem:PRPerOrb},
one can find a sequence $s_{n}\rightarrow\infty$ such that the following
properties hold true:

\vspace{2mm}\noindent (i) $z_{n}:=\phi_{s_{n}}(x)\in\Sigma$ and
$\phi_{s_{n}}(x)\rightarrow p$;

\vspace{2mm}\noindent (ii) $\phi_{t}(x)\notin\Sigma$ for $t\in(s_{n-1},s_{n})$;

\vspace{2mm}\noindent (iii) the sequence $z_{1},z_{2},z_{3},\cdots$
is monotone on $\Sigma.$\begin{figure}[H] 
\begin{center}  
\includegraphics[scale=0.14]{lim_po} 
\end{center}
\end{figure}\noindent Consequently, one has 
\begin{equation}
z_{n}\downarrow p\quad\text{or}\quad z_{n}\uparrow p\quad\text{on }\Sigma.\label{eq:MonoPerObLemPf}
\end{equation}
Note that $z_{n+1}=P(z_{n})$ for all sufficiently large $n,$ where
$P$ is the Poincar\'e map defined in Section \ref{subsec:PoinMap}.
By the continuity of the Poincar\'e map, one has 
\begin{equation}
\lim_{z\rightarrow p}\sup_{0\leqslant t\leqslant\tau(z)}d(\phi_{t}(z),C)=0,\label{eq:1IterAsymp}
\end{equation}
where $\tau(z)$ is the first return time of $\phi_{t}(z)$ to $\Sigma$.
The claim (\ref{eq:OrbAsymC}) is now a simple consequence of the
monotone convergence property (\ref{eq:MonoPerObLemPf}) and the one-iteration
asymptotics (\ref{eq:1IterAsymp}).
